    $('#srNat', ov).onchange = () => { const n = i.natures[$('#srNat', ov).value]; if (n) $('#srLoss', ov).value = n.loss.toFixed(2); note(); }; $('#srTot', ov).oninput = note;
    $('#srNo', ov).onclick = close; $('#srOk', ov).onclick = async () => { try { const x = await api(`sales/${r.id}/refund`, { method: 'POST', body: { sale_rate: $('#srRate', ov).value, total_amount: $('#srTot', ov).value, nature: $('#srNat', ov).value, loss_amount: $('#srLoss', ov).value, reason: $('#srWhy', ov).value } }); close(); toast(x.message); again(); } catch (e) { $('#srMsg', ov).textContent = e.message; } };
