      <div class="card" style="margin-top:14px"><div class="card-h"><h3>Allowed addresses</h3><span class="small muted">no rule for a person = he can sign in from anywhere</span></div><div class="tbl-wrap"><table class="t"><thead><tr><th>For</th><th>Address or range</th><th>Note</th><th>Added</th><th></th></tr></thead><tbody>${d.rules.map(x => `<tr><td>${x.scope === 'ALL' ? 'Everybody' : x.scope === 'ROLE' ? 'Role ' + esc(x.role_code) : 'User ' + esc(x.login_id || '')}</td><td><code>${esc(x.ip_cidr)}</code></td><td>${esc(x.source_note || '')}</td><td>${esc((x.created_at || '').slice(0, 10))}</td><td>${d.can_rules ? `<button class="btn sm" data-ir="${x.id}">Remove</button>` : ''}</td></tr>`).join('')}</tbody></table>${d.rules.length ? '' : '<div class="empty">No rule: everybody can sign in from anywhere.</div>'}</div></div>
