    $$('#main [data-cup]').forEach(b => { b.onclick = () => { const u = d.customs.find(x => x.id == b.dataset.cup); miniForm(`Pay customs ${u.customs_code}`, 'Leave the amounts empty to pay what the entry says, changed into the bank\'s currency.', [{ name: 'bank', label: 'Paid from', required: true, options: opt(d.banks, x => [x.id, `${x.name} (${x.currency})`]) }, { name: 'date', label: 'Date', type: 'date', required: true, value: S.boot.today }, { name: 'duty', label: 'Duty paid (bank currency)', type: 'number' }, { name: 'import_vat', label: 'Import VAT paid (bank currency)', type: 'number' }],
      async v => { const r = await api(`customs/${u.id}/pay`, { method: 'POST', body: { bank: +v.bank, date: v.date, duty: v.duty === '' ? null : +v.duty, import_vat: v.import_vat === '' ? null : +v.import_vat } }); again(); return r; }, 'Pay'); }; });
    if ($('#cuAdd')) $('#cuAdd').onclick = () => miniForm('New customs entry', 'Duty is worked out from the value and the rate unless you type the amount on the customs papers.', [{ name: 'shipment', label: 'Shipment', required: true, options: opt(d.shipments, x => [x.id, x.shipment_code]) }, { name: 'declaration_number', label: 'Declaration number' }, { name: 'hs_code', label: 'HS code' }, { name: 'customs_value', label: 'Customs value', type: 'number', required: true },
      { name: 'currency', label: 'Currency', options: curOpts, value: d.base }, { name: 'duty_rate', label: 'Duty rate %', type: 'number', value: 0 }, { name: 'duty_amount', label: 'Duty amount (empty = value × rate)', type: 'number' }, { name: 'import_vat', label: 'Import VAT', type: 'number', value: 0 }, { name: 'clearance_date', label: 'Cleared on', type: 'date' }],
      async v => { const r = await api('customs', { method: 'POST', body: { shipment: +v.shipment, declaration_number: v.declaration_number || null, hs_code: v.hs_code || null, customs_value: +v.customs_value || 0, currency: v.currency, duty_rate: +v.duty_rate || 0, duty_amount: v.duty_amount === '' ? null : +v.duty_amount, import_vat: +v.import_vat || 0, clearance_date: v.clearance_date || null } }); again(); return r; }, 'Save');
    const qcForm = reOf => { const prev = reOf ? d.qcs.find(q => q.id == reOf) : null; const start = prev ? prev.checks.map(k => k.text) : d.template;
      const row = t => `<tr data-k><td><input class="q" data-kt value="${esc(t || '')}" placeholder="What is checked" style="min-width:160px;width:100%"></td><td><select class="q" data-kr><option>PASS</option><option>FAIL</option><option selected>NA</option></select></td><td><input class="q" data-kn placeholder="Note" style="min-width:110px;width:100%"></td><td><input type="file" accept="image/*" data-kf style="max-width:150px"><span data-kid></span></td></tr>`;
      const { ov, close } = modal(prev ? `Re-inspection of ${prev.qc_code}` : 'New quality check', 'A failed check needs a note and a photo. Any failed check makes the QC FAILED unless you pass it with a written reason.',
        `<div class="form" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:8px"><div class="fld is-req"><label>PO</label><select id="qP">${d.pos.map(x => `<option value="${x.id}" ${prev && prev.fk_id_po == x.id ? 'selected' : ''}>${esc(x.po_number)}</option>`).join('')}</select></div><div class="fld"><label>Inspector</label><input id="qI"></div><div class="fld is-req"><label>Date</label><input id="qD" type="date" value="${S.boot.today}"></div>
          <div class="fld is-req"><label>Inspected</label><input id="qN" type="number" min="0" value="0"></div><div class="fld is-req"><label>Passed</label><input id="qOk" type="number" min="0" value="0"></div><div class="fld is-req"><label>Failed</label><input id="qF" type="number" min="0" value="0"></div></div>
         <div class="tbl-wrap" style="margin-top:8px"><table class="t"><thead><tr><th>Check</th><th>Result</th><th>Note</th><th>Photo</th></tr></thead><tbody id="qK">${(start.length ? start : ['', '', '']).map(row).join('')}</tbody></table></div><button class="btn sm" id="qKAdd" style="margin-top:6px">${ic('plus')} Check</button>
         <div class="form" style="margin-top:8px"><div class="fld"><label class="chk"><input type="checkbox" id="qOv"> Pass it even with a failed check</label></div><div class="fld"><label>Reason for passing</label><input id="qOvR"></div><div class="fld"><label>Corrective action</label><input id="qCa"></div></div>`,
        `<span class="left small muted" id="qMsg"></span><button class="btn" id="qCancel">Cancel</button><button class="btn primary" id="qSave">Save QC</button>`);
      $('#qCancel', ov).onclick = close; $('#qKAdd', ov).onclick = () => $('#qK', ov).insertAdjacentHTML('beforeend', row(''));
      $('#qSave', ov).onclick = async () => { busy(true); try {
        const checks = []; for (const tr of $$('#qK tr', ov)) { const t = $('[data-kt]', tr).value.trim(); if (!t) continue; let photo = +($('[data-kid]', tr).dataset.id || 0) || null; const f = $('[data-kf]', tr).files[0];
          if (f && !photo) { const u = await upload('qc/photo', { file: f }); photo = u.id; $('[data-kid]', tr).dataset.id = u.id; } checks.push({ text: t, result: $('[data-kr]', tr).value, note: $('[data-kn]', tr).value || null, photo }); }
        const r = await api('qc', { method: 'POST', body: { po: +$('#qP', ov).value, inspector: $('#qI', ov).value || null, inspection_date: $('#qD', ov).value, qty_inspected: +$('#qN', ov).value || 0, qty_passed: +$('#qOk', ov).value || 0, qty_failed: +$('#qF', ov).value || 0, checks, re_inspection_of: prev ? prev.id : null, override_pass: $('#qOv', ov).checked, override_reason: $('#qOvR', ov).value || null, corrective_action: $('#qCa', ov).value || null } });
        close(); toast(r.message, r.result === 'FAILED' ? 'err' : 'ok'); again(); } catch (e) { $('#qMsg', ov).textContent = e.message; } busy(false); }; };
